""" Generate a filename to output results to, with no file extension. """
def generate_results_file_name(world_folder: Any) -> object {
    name = world_folder;
    if (world_folder[:9] == "tw_games/") {
        if (world_folder[-1:] == "/") {
            name = world_folder[9:-1];
        } else {
            name = world_folder[9:];
        }
    } else {
        name = world_folder;
    }
    return ("test_results/" + name);
}

